-- Register the existing approved website files without copying or changing image bytes.
-- One-shot import markers prevent reruns from restoring deliberately removed photos.
CREATE TABLE IF NOT EXISTS website_media_imports (id TEXT PRIMARY KEY,completed INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO website_media_imports(id) VALUES ('existing-website-photos-20261019-609-golden-gate-pt');
